// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";

/**
 * @title PartnerRegister
 * @dev Tracks partner share percentages and mints non-transferable SBTs per project.
 */
contract PartnerRegister is ERC721, Ownable {
    struct PartnerInfo {
        uint256 shareBps;
        bool exists;
    }

    bytes32 public immutable projectId;
    address public controller; // governance module
    uint256 public totalShareBps;
    uint256 private _tokenIdTracker;

    mapping(address => PartnerInfo) public partners;
    mapping(address => uint256) public partnerTokenId;

    event ControllerUpdated(address indexed newController);
    event PartnerUpdated(address indexed account, uint256 shareBps);
    event PartnerRevoked(address indexed account);

    constructor(
        bytes32 _projectId,
        string memory projectName,
        string memory projectSymbol,
        address founder
    ) ERC721(projectName, projectSymbol) Ownable(msg.sender) {
        projectId = _projectId;
        if (founder != address(0)) {
            partners[founder] = PartnerInfo({shareBps: 10_000, exists: true});
            totalShareBps = 10_000;
            _mintSBT(founder);
            emit PartnerUpdated(founder, 10_000);
        }
    }

    modifier onlyController() {
        require(msg.sender == controller, "Not controller");
        _;
    }

    function setController(address _controller) external onlyOwner {
        require(_controller != address(0), "Invalid controller");
        controller = _controller;
        emit ControllerUpdated(_controller);
    }

    function getShareBps(address account) external view returns (uint256) {
        return partners[account].shareBps;
    }

    function addPartner(address account, uint256 shareBps) external onlyController {
        require(account != address(0), "Invalid account");
        require(shareBps > 0, "Share = 0");
        require(totalShareBps + shareBps <= 10_000, "Exceeds 100%");
        totalShareBps += shareBps;
        if (!partners[account].exists) {
            partners[account] = PartnerInfo({shareBps: shareBps, exists: true});
            _mintSBT(account);
        } else {
            partners[account].shareBps += shareBps;
        }
        emit PartnerUpdated(account, partners[account].shareBps);
    }

    function reducePartnerShare(address account, uint256 shareBps) external onlyController {
        PartnerInfo storage info = partners[account];
        require(info.exists, "Partner missing");
        require(shareBps > 0 && shareBps <= info.shareBps, "Invalid share");
        info.shareBps -= shareBps;
        totalShareBps -= shareBps;
        if (info.shareBps == 0) {
            _revokePartner(account);
        } else {
            emit PartnerUpdated(account, info.shareBps);
        }
    }

    function renouncePartnership() external {
        require(partners[msg.sender].shareBps > 0, "No share");
        uint256 share = partners[msg.sender].shareBps;
        partners[msg.sender].shareBps = 0;
        partners[msg.sender].exists = false;
        totalShareBps -= share;
        _burnPartner(msg.sender);
        emit PartnerRevoked(msg.sender);
    }

    function revokePartner(address account) external onlyController {
        _revokePartner(account);
    }

    function _revokePartner(address account) internal {
        PartnerInfo storage info = partners[account];
        require(info.exists, "Partner missing");
        uint256 share = info.shareBps;
        totalShareBps -= share;
        info.shareBps = 0;
        info.exists = false;
        _burnPartner(account);
        emit PartnerRevoked(account);
    }

    function _mintSBT(address to) internal {
        uint256 tokenId = ++_tokenIdTracker;
        partnerTokenId[to] = tokenId;
        _safeMint(to, tokenId);
    }

    function _burnPartner(address account) internal {
        uint256 tokenId = partnerTokenId[account];
        if (tokenId != 0 && _ownerOf(tokenId) != address(0)) {
            _burn(tokenId);
        }
        delete partnerTokenId[account];
    }

    // Soulbound: block transfers except mint/burn
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address) {
        address from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0) && from != to) {
            revert("SBT non-transferable");
        }
        return super._update(to, tokenId, auth);
    }
}

contracts/v4/ProfitVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IPartnerRegister {
    function getShareBps(address account) external view returns (uint256);
}

/**
 * @title ProfitVault
 * @dev Holds project earnings (ERC20) and manages distribution cycles with automatic 2% fee forwarding.
 */
contract ProfitVault is Ownable {
    struct DistributionPeriod {
        uint256 totalAmount;
        uint256 feeAmount;
        bool claimable;
    }

    IERC20 public immutable payoutToken;
    address public immutable treasury;
    uint16 public immutable feeBps;
    address public governanceModule;
    IPartnerRegister public partnerRegister;

    // periodId => info
    mapping(bytes32 => DistributionPeriod) public periods;
    // periodId => account => claimed
    mapping(bytes32 => mapping(address => bool)) public hasClaimed;

    event Deposit(address indexed from, uint256 amount);
    event DistributionStarted(bytes32 indexed periodId, uint256 amount, uint256 fee);
    event Claimed(bytes32 indexed periodId, address indexed account, uint256 amount);

    constructor(
        address _payoutToken,
        address _treasury,
        uint16 _feeBps,
        address _governance,
        address _partnerRegister
    ) Ownable(msg.sender) {
        require(_payoutToken != address(0) && _treasury != address(0), "Invalid address");
        require(_feeBps <= 1000, "Fee too high"); // max 10%
        payoutToken = IERC20(_payoutToken);
        treasury = _treasury;
        feeBps = _feeBps;
        governanceModule = _governance;
        partnerRegister = IPartnerRegister(_partnerRegister);
    }

    modifier onlyGovernance() {
        require(msg.sender == governanceModule, "Not governance");
        _;
    }

    function setGovernance(address _gov) external onlyOwner {
        require(_gov != address(0), "Invalid governance");
        governanceModule = _gov;
    }

    function setPartnerRegister(address _register) external onlyOwner {
        partnerRegister = IPartnerRegister(_register);
    }

    /**
     * @notice Deposit earnings (pull pattern)
     */
    function deposit(uint256 amount) external {
        require(amount > 0, "Amount = 0");
        require(payoutToken.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        emit Deposit(msg.sender, amount);
    }

    /**
     * @notice Starts a distribution period and forwards the 2% fee.
     */
    function startDistribution(bytes32 periodId) external onlyGovernance {
        DistributionPeriod storage period = periods[periodId];
        require(period.totalAmount == 0, "Already started");
        uint256 balance = payoutToken.balanceOf(address(this));
        require(balance > 0, "No funds");
        uint256 fee = (balance * feeBps) / 10_000;
        if (fee > 0) {
            require(payoutToken.transfer(treasury, fee), "Fee transfer failed");
        }
        period.totalAmount = balance - fee;
        period.feeAmount = fee;
        period.claimable = true;
        emit DistributionStarted(periodId, period.totalAmount, fee);
    }

    /**
     * @notice Emergency/ops path: Owner may start distribution directly.
     * This mirrors startDistribution logic for operational control.
     */
    function ownerStartDistribution(bytes32 periodId) external onlyOwner {
        DistributionPeriod storage period = periods[periodId];
        require(period.totalAmount == 0, "Already started");
        uint256 balance = payoutToken.balanceOf(address(this));
        require(balance > 0, "No funds");
        uint256 fee = (balance * feeBps) / 10_000;
        if (fee > 0) {
            require(payoutToken.transfer(treasury, fee), "Fee transfer failed");
        }
        period.totalAmount = balance - fee;
        period.feeAmount = fee;
        period.claimable = true;
        emit DistributionStarted(periodId, period.totalAmount, fee);
    }

    /**
     * @notice Partners call this to receive their share for the current period.
     */
    function claim(bytes32 periodId) external {
        DistributionPeriod storage period = periods[periodId];
        require(period.claimable, "Not claimable");
        require(!hasClaimed[periodId][msg.sender], "Already claimed");
        uint256 shareBps = partnerRegister.getShareBps(msg.sender);
        require(shareBps > 0, "No share");
        uint256 amount = (period.totalAmount * shareBps) / 10_000;
        require(amount > 0, "Zero payout");
        hasClaimed[periodId][msg.sender] = true;
        require(payoutToken.transfer(msg.sender, amount), "Transfer failed");
        emit Claimed(periodId, msg.sender, amount);
    }
}

contracts/v4/ProjectFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

import "./PartnerRegister.sol";
import "./GovernanceModule.sol";
import "./ProfitVault.sol";
import "./CapitalVault.sol";

/**
 * @title ProjectFactory
 * @dev Deploys per-project contract suites and tracks their addresses.
 */
contract ProjectFactory is Ownable {
    struct ProjectContracts {
        address partnerRegister;
        address governanceModule;
        address profitVault;
        address capitalVault;
    }

    mapping(bytes32 => ProjectContracts) public projects;
    address public immutable treasury;
    uint16 public immutable feeBps;
    address public payoutToken;
    address public capitalToken;

    event ProjectCreated(
        bytes32 indexed projectId,
        address indexed founder,
        ProjectContracts contractsDeployed
    );

    constructor(
        address _treasury,
        uint16 _feeBps,
        address _payoutToken,
        address _capitalToken
    ) Ownable(msg.sender) {
        require(_treasury != address(0), "Invalid treasury");
        require(_feeBps <= 1000, "Fee too high");
        treasury = _treasury;
        feeBps = _feeBps;
        payoutToken = _payoutToken;
        capitalToken = _capitalToken;
    }

    function setTokens(address _payoutToken, address _capitalToken) external onlyOwner {
        payoutToken = _payoutToken;
        capitalToken = _capitalToken;
    }

    function createProject(
        string calldata slug,
        address founder
    ) external onlyOwner returns (bytes32) {
        require(founder != address(0), "Invalid founder");
        bytes32 projectId = keccak256(abi.encodePacked(blockhash(block.number - 1), slug, founder));
        require(projects[projectId].partnerRegister == address(0), "Project exists");

        PartnerRegister register = new PartnerRegister(
            projectId,
            string.concat("Partner ", slug),
            string.concat("SBT-", slug),
            founder
        );
        GovernanceModule governance = new GovernanceModule(address(register));
        register.setController(address(governance));
        register.transferOwnership(owner());

        ProfitVault profitVault = new ProfitVault(
            payoutToken,
            treasury,
            feeBps,
            address(governance),
            address(register)
        );
        profitVault.transferOwnership(owner());

        CapitalVault capitalVault = new CapitalVault(capitalToken, address(governance));
        capitalVault.transferOwnership(owner());

        projects[projectId] = ProjectContracts({
            partnerRegister: address(register),
            governanceModule: address(governance),
            profitVault: address(profitVault),
            capitalVault: address(capitalVault)
        });

        emit ProjectCreated(projectId, founder, projects[projectId]);
        return projectId;
    }
}

